def previous_handle_baseline_source(path, value):
    from new_object_policy_wiring import previous_new_object_policy_source
    value = previous_new_object_policy_source(path, value)
    for current, previous in CHANGES.get(path, ()):
        assert value.count(current) == 1, f"handle baseline hunk changed: {path}"
        value = value.replace(current, previous, 1)
    return value
